-- Recipes table. Run in the Supabase dashboard → SQL Editor, then run
-- supabase/recipes_data.sql to fill it. Safe to re-run: it keeps the table
-- when it already has this shape.
--
-- Rows are generated by scripts/recipes/build.mjs from data/recipes/*.json.
-- Calories and macros are computed there from data/ingredients.json, per serving.

-- The first version of this table had fixed protein/carb/vegetable/sauce columns.
do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'recipes' and column_name = 'ingredient_quantities'
  ) then
    drop table public.recipes;
  end if;
end $$;

create table if not exists public.recipes (
  id            text primary key,
  name          text not null,
  description   text not null,
  meal_type     text not null check (meal_type in ('breakfast', 'lunch', 'dinner')),
  -- Key of the ingredient the dish is built around (data/ingredients.json).
  main          text not null,
  emoji         text not null,
  prep_time_min int  not null,
  difficulty    text not null,
  calories      int  not null,
  protein_g     int  not null,
  carbs_g       int  not null,
  fat_g         int  not null,
  fiber_g       int  not null,
  sugar_g       int  not null,
  sodium_mg     int  not null,
  -- [{ name, amount, unit, label? }]: what the app shows and puts on the shopping list.
  ingredients   jsonb not null,
  -- Salt, spices, water: shown with the recipe, not counted or shopped for.
  seasonings    jsonb not null default '[]',
  instructions  jsonb not null,
  appliances    jsonb not null default '[]',
  keywords      jsonb not null default '[]',
  dietary_tags  jsonb not null default '[]',
  sort          int  not null default 0,
  updated_at    timestamptz not null default now()
);

alter table public.recipes enable row level security;

drop policy if exists "recipes readable by everyone" on public.recipes;
create policy "recipes readable by everyone"
  on public.recipes for select to anon, authenticated using (true);
